/**
 * Instruction composition.
 *
 * Instruction is the only kind where several artifacts share one target
 * (AGENTS.md). Rather than letting the first source win, every instruction
 * source in a scope is concatenated into one generated file in the loadout
 * root, and every instruction destination is a symlink to it.
 *
 * No CLI imports: this module is bundled into embedded runtimes.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { fileExists, hashContent, hashFile, isDirectory, isSymlink, readFile } from "../lib/fs.js";
import { registry } from "./registry.js";
import type { AppliedState, ManifestEntry, RenderPlan, ResolvedLoadout, Scope } from "./types.js";

export const GENERATED_INSTRUCTIONS_FILE = "AGENTS.loadouts-generated.md";
export const GENERATED_INSTRUCTIONS_BACKUP = `${GENERATED_INSTRUCTIONS_FILE}.bak`;

export function isComposedKind(kind: string): boolean {
  return kind === "instruction";
}

export interface ComposedSource {
  loadout: string;
  sourcePath: string;
  displayPath: string;
  body: string;
  hash: string;
}

export interface ComposedDestination {
  targetPath: string;
  tools: string[];
}

export interface Composition {
  generatedPath: string;
  content: string;
  hash: string;
  sources: ComposedSource[];
  destinations: ComposedDestination[];
  warnings: string[];
}

export interface SectionEdit {
  owner: { loadout: string; displayPath: string; sourcePath: string } | null;
  before: string;
  after: string;
}

export interface InstructionConflict {
  path: string;
  displayPath: string;
  reason: "edited" | "replaced";
  edits: SectionEdit[];
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function resolveTarget(targetPath: string, projectRoot: string): string {
  return path.isAbsolute(targetPath) ? targetPath : path.join(projectRoot, targetPath);
}

function realpathOr(p: string): string {
  try {
    return fs.realpathSync(p);
  } catch {
    return path.resolve(p);
  }
}

/**
 * Human-facing path: relative to the project when inside it, otherwise
 * absolute with the home directory shown as `~`. At global scope the
 * "project" is the home directory, so paths there always use the `~` form.
 */
export function instructionDisplayPath(filePath: string, projectRoot: string): string {
  const abs = path.resolve(projectRoot, filePath);
  const home = os.homedir();
  const root = path.resolve(projectRoot);
  if (root !== home && abs.startsWith(root + path.sep)) {
    return path.relative(root, abs);
  }
  if (abs === home) return "~";
  if (abs.startsWith(home + path.sep)) {
    return `~${path.sep}${path.relative(home, abs)}`;
  }
  return abs;
}

function trimBody(raw: string): string {
  return raw.replace(/\s+$/, "");
}

function readSourceBody(sourcePath: string): string | null {
  try {
    return trimBody(readFile(sourcePath));
  } catch {
    return null;
  }
}

function toolDisplayName(toolName: string): string {
  return toolName
    .split("-")
    .map((part) => (part ? part[0].toUpperCase() + part.slice(1) : part))
    .join(" ");
}

function formatComposition(sources: ComposedSource[]): string {
  const header = [
    "<!--",
    "  Generated by loadouts. Do not edit this file.",
    "  `loadouts sync` will not overwrite local edits here; it reports them instead.",
    "  Edit the source named in each section, then run `loadouts sync`:",
    ...sources.map((s) => `    - ${s.displayPath} (loadout: ${s.loadout})`),
    "-->",
  ].join("\n");

  const sections = sources.map(
    (s) =>
      `<!-- loadouts:begin ${s.loadout} · ${s.displayPath} -->\n` +
      `${s.body}\n` +
      `<!-- loadouts:end ${s.loadout} · ${s.displayPath} -->`
  );

  return [header, ...sections].join("\n\n") + "\n";
}

/**
 * Size and suppression warnings for a composition's destinations. Depends on
 * what is on disk, so callers may recompute it after pruning stale outputs.
 */
export function computeInstructionWarnings(
  content: string,
  destinations: ComposedDestination[],
  projectRoot: string,
  scope: Scope
): string[] {
  const warnings: string[] = [];
  const bytes = Buffer.byteLength(content, "utf8");

  for (const dest of destinations) {
    const destName = instructionDisplayPath(resolveTarget(dest.targetPath, projectRoot), projectRoot);
    for (const toolName of dest.tools) {
      const info = registry.getTool(toolName)?.instructions;
      if (!info) continue;

      if (info.maxBytes !== undefined && bytes > info.maxBytes) {
        warnings.push(
          `${destName} is ${(bytes / 1024).toFixed(1)} KiB; ${toolName} reads only the first ` +
            `${info.maxBytes / 1024} KiB (project_doc_max_bytes). Trim instructions or raise ` +
            `project_doc_max_bytes in ~/.codex/config.toml.`
        );
      }

      if (scope === "project") {
        for (const rel of info.suppressedBy ?? []) {
          if (fileExists(path.join(projectRoot, rel))) {
            warnings.push(
              `${toolDisplayName(toolName)} reads ${rel} instead of ${destName} while ${rel} exists; ` +
                `move its content into an instruction source and delete it.`
            );
          }
        }
      }
    }
  }

  return warnings;
}

// ---------------------------------------------------------------------------
// Compose
// ---------------------------------------------------------------------------

/**
 * Concatenate the instruction sources of all plans into one generated file.
 * Returns null when no plan has an instruction output.
 */
export function composeInstructions(
  plans: Array<{ loadout: ResolvedLoadout; plan: RenderPlan }>,
  opts: { loadoutRoot: string; projectRoot: string; scope: Scope }
): Composition | null {
  const destinations = new Map<string, Set<string>>();
  const sources: ComposedSource[] = [];
  const seenSources = new Set<string>();

  for (const { loadout, plan } of plans) {
    for (const { spec } of plan.outputs) {
      if (!isComposedKind(spec.kind)) continue;

      const tools = destinations.get(spec.targetPath) ?? new Set<string>();
      tools.add(spec.tool);
      destinations.set(spec.targetPath, tools);

      const identity = realpathOr(spec.sourcePath);
      if (seenSources.has(identity)) continue;
      seenSources.add(identity);

      const body = trimBody(readFile(spec.sourcePath));
      sources.push({
        loadout: loadout.name,
        sourcePath: spec.sourcePath,
        displayPath: instructionDisplayPath(spec.sourcePath, opts.projectRoot),
        body,
        hash: hashContent(body),
      });
    }
  }

  if (destinations.size === 0) return null;

  const content = formatComposition(sources);
  const destinationList: ComposedDestination[] = [...destinations.entries()].map(
    ([targetPath, tools]) => ({ targetPath, tools: [...tools].sort() })
  );

  return {
    generatedPath: path.join(opts.loadoutRoot, GENERATED_INSTRUCTIONS_FILE),
    content,
    hash: hashContent(content),
    sources,
    destinations: destinationList,
    warnings: computeInstructionWarnings(content, destinationList, opts.projectRoot, opts.scope),
  };
}

// ---------------------------------------------------------------------------
// Parse
// ---------------------------------------------------------------------------

/**
 * Split a generated file into its marked sections. Returns null when no
 * section is found or any begin marker lacks its matching end marker.
 */
export function parseSections(
  content: string
): Array<{ loadout: string; displayPath: string; body: string }> | null {
  const re = /^<!-- loadouts:begin (.+?) · (.+?) -->\n([\s\S]*?)\n<!-- loadouts:end \1 · \2 -->$/gm;
  const sections = [...content.matchAll(re)].map((m) => ({
    loadout: m[1],
    displayPath: m[2],
    body: m[3],
  }));
  if (sections.length === 0) return null;

  const begins = content.match(/^<!-- loadouts:begin .+ -->$/gm)?.length ?? 0;
  if (begins !== sections.length) return null;

  return sections;
}

// ---------------------------------------------------------------------------
// Conflicts
// ---------------------------------------------------------------------------

function attributeEdits(
  edited: string,
  entry: ManifestEntry,
  composition: Composition | null,
  projectRoot: string
): SectionEdit[] {
  const whole: SectionEdit[] = [{ owner: null, before: composition?.content ?? "", after: edited }];
  if (!entry.sources) return whole;

  const recorded = entry.sources.map((s) => ({
    ...s,
    displayPath: instructionDisplayPath(s.path, projectRoot),
  }));
  const parsed = parseSections(edited);
  if (!parsed) return whole;

  const parsedPaths = parsed.map((s) => s.displayPath).sort();
  const recordedPaths = recorded.map((s) => s.displayPath).sort();
  if (
    parsedPaths.length !== recordedPaths.length ||
    parsedPaths.some((p, i) => p !== recordedPaths[i])
  ) {
    return whole;
  }

  const edits: SectionEdit[] = [];
  for (const section of parsed) {
    const rec = recorded.find((r) => r.displayPath === section.displayPath)!;
    if (hashContent(section.body) === rec.hash) continue;
    edits.push({
      owner: { loadout: section.loadout, displayPath: rec.displayPath, sourcePath: rec.path },
      before: readSourceBody(rec.path) ?? "",
      after: section.body,
    });
  }

  // Edits outside any section (e.g. the header) still count as an edit.
  return edits.length > 0 ? edits : whole;
}

/**
 * Find local edits to composed instruction files recorded in state:
 * an edited generated file, or a destination replaced by a regular file.
 */
export function detectInstructionConflicts(
  state: AppliedState | null,
  composition: Composition | null,
  projectRoot: string
): InstructionConflict[] {
  if (!state) return [];

  const composed = state.entries.filter((e) => isComposedKind(e.kind));
  const conflicts: InstructionConflict[] = [];

  const editedEntry = composed.find(
    (e) =>
      e.sources &&
      fileExists(e.sourcePath) &&
      !isDirectory(e.sourcePath) &&
      hashFile(e.sourcePath) !== e.renderedHash
  );
  if (editedEntry) {
    const edited = readFile(editedEntry.sourcePath);
    conflicts.push({
      path: editedEntry.sourcePath,
      displayPath: instructionDisplayPath(editedEntry.sourcePath, projectRoot),
      reason: "edited",
      edits: attributeEdits(edited, editedEntry, composition, projectRoot),
    });
  }

  for (const entry of composed) {
    const fullPath = resolveTarget(entry.targetPath, projectRoot);
    if (!fileExists(fullPath) || isSymlink(fullPath) || isDirectory(fullPath)) continue;
    if (hashFile(fullPath) === entry.renderedHash) continue;

    const edited = readFile(fullPath);
    conflicts.push({
      path: fullPath,
      displayPath: instructionDisplayPath(fullPath, projectRoot),
      reason: "replaced",
      edits: attributeEdits(edited, entry, composition, projectRoot),
    });
  }

  return conflicts;
}
